        File f = new File(directory, file);

        // Check if it is a directory
        if (f.isDirectory()) {
            // If it is a directory, delete it and all sub-directories
            deleteDirectory(f);
        } else {
            // If it is a file, delete it directly
            if (!f.delete()) {
                throw new IOException("Error deleting file " + f.getName());
            }
        }
    }

