private static int searchClosestPrime(int desiredCapacity, List<Integer> closestPrimeList) {
	int left = 0;
	int right = closestPrimeList.size() - 1;

	while (left <= right) {
		int middle = (left + right) / 2;
		int closestPrime = closestPrimeList.get(middle);

		if (closestPrime == desiredCapacity) {
			return closestPrime;
		}
