/**
 * Convert process properties to source data
 *
 * @param properties list of process properties to convert
 * @return JsonObject representing the source data
 */
public JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject sourceData = new JsonObject();

    for (KeyStringValuePair property : properties) {
        String key = property.getKey();
        String value = property.getValue().toString();

        if (value.isEmpty()) {
            sourceData.addProperty(key, value);
        } else {
            try {
                sourceData.addProperty(key, value);
            } catch (UnsupportedOperationException e) {
                // handle unsupported property type
                e.printStackTrace();
            }
        }
    }

    return sourceData;
}

